import { z } from "zod";
import {
  isoTimestampSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const activityActionSchema = z.enum([
  "organization.updated",
  "project.created",
  "project.updated",
  "project.archived",
  "project.restored",
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.restored",
  "comment.created",
  "comment.updated",
  "comment.deleted",
  "member.invited",
  "member.joined",
  "member.role_changed",
  "member.removed",
  "billing.plan_changed",
  "flag.toggled",
]);

export const activitySubjectKindSchema = z.enum([
  "organization",
  "project",
  "issue",
  "comment",
  "member",
  "subscription",
  "feature_flag",
]);

export const activityFilterSchema = z
  .object({
    orgId: orgIdSchema,
    action: z.array(activityActionSchema).optional(),
    actorId: userIdSchema.optional(),
    projectId: projectIdSchema.optional(),
    subjectKind: activitySubjectKindSchema.optional(),
    since: isoTimestampSchema.optional(),
    until: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape);

export const exportActivitySchema = z.object({
  orgId: orgIdSchema,
  since: isoTimestampSchema,
  until: isoTimestampSchema,
  format: z.enum(["csv", "json"]).default("csv"),
});

export type ActivityFilterInput = z.infer<typeof activityFilterSchema>;
export type ExportActivityInput = z.infer<typeof exportActivitySchema>;
import { z } from "zod";
import { emailSchema, invitationIdSchema, orgIdSchema } from "./common";
import { invitableRoleSchema } from "./role";

/** Invitation lifecycle, kept apart from `member.ts` because the accept flow
 *  runs unauthenticated (the token is the credential). */
export const invitationTokenSchema = z
  .string()
  .min(32)
  .max(128)
  .regex(/^[A-Za-z0-9_-]+$/, "malformed invitation token");

export const createInvitationSchema = z.object({
  orgId: orgIdSchema,
  email: emailSchema,
  role: invitableRoleSchema,
  expiresInDays: z.number().int().min(1).max(30).default(14),
});

export const resendInvitationSchema = z.object({
  orgId: orgIdSchema,
  invitationId: invitationIdSchema,
});

export const acceptInvitationTokenSchema = z.object({
  token: invitationTokenSchema,
});

export type CreateInvitationInput = z.infer<typeof createInvitationSchema>;
export type AcceptInvitationTokenInput = z.infer<
  typeof acceptInvitationTokenSchema
>;
import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
  WebhookId,
} from "@/types/common";

/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
/**
 * Barrel for the Zod contract. Client forms import the individual schema they
 * bind to a resolver; Server Actions import the same symbol. Never redeclare a
 * shape locally — extend the schema here instead.
 */
export * from "./common";
export * from "./slug";
export * from "./role";
export * from "./auth";
export * from "./session";
export * from "./organization";
export * from "./member";
export * from "./invitation";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./label";
export * from "./attachment";
export * from "./notification";
export * from "./activity";
export * from "./billing";
export * from "./feature-flag";
export * from "./search";
export * from "./webhook";
export * from "./export";
export * from "./pagination";
import { z } from "zod";
import {
  emailSchema,
  memberIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";
import { invitableRoleSchema, memberStatusSchema, roleSchema } from "./role";

export const inviteMemberSchema = z.object({
  orgId: orgIdSchema,
  email: emailSchema,
  role: invitableRoleSchema.default("member"),
  message: z.string().max(500).optional(),
});

/** Bulk invite from the members settings page; the seat check runs once. */
export const inviteMembersSchema = z.object({
  orgId: orgIdSchema,
  invites: z
    .array(
      z.object({
        email: emailSchema,
        role: invitableRoleSchema.default("member"),
      }),
    )
    .min(1)
    .max(50),
});

export const acceptInvitationSchema = z.object({
  token: z.string().min(16),
});

export const revokeInvitationSchema = z.object({
  orgId: orgIdSchema,
  invitationId: z.string().min(1),
});

export const updateMemberRoleSchema = z.object({
  orgId: orgIdSchema,
  memberId: memberIdSchema,
  role: roleSchema,
});

export const removeMemberSchema = z.object({
  orgId: orgIdSchema,
  memberId: memberIdSchema,
});

export const listMembersSchema = z
  .object({
    orgId: orgIdSchema,
    role: roleSchema.optional(),
    status: memberStatusSchema.optional(),
    query: z.string().max(200).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateProfileSchema = z.object({
  userId: userIdSchema,
  name: z.string().min(1).max(80).optional(),
  avatarUrl: z.url().nullable().optional(),
  timezone: z.string().min(1).max(64).optional(),
});

export type InviteMemberInput = z.infer<typeof inviteMemberSchema>;
export type InviteMembersInput = z.infer<typeof inviteMembersSchema>;
export type UpdateMemberRoleInput = z.infer<typeof updateMemberRoleSchema>;
export type RemoveMemberInput = z.infer<typeof removeMemberSchema>;
export type ListMembersInput = z.infer<typeof listMembersSchema>;
export type UpdateProfileInput = z.infer<typeof updateProfileSchema>;
/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
