import type { IsoTimestamp, OrgId, UserId } from "./common";

/**
 * What a personal API token may do. A `read` token always acts as a viewer; a
 * `write` token acts with its owner's current role in the organization.
 */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the app sees it. The secret is shown exactly once,
 * when the token is minted, and only its hash is stored — neither ever appears
 * on this type.
 */
export interface ApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  /** The first characters of the secret, so a user can tell tokens apart. */
  prefix: string;
  expiresAt: IsoTimestamp;
  lastUsedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}

