/**
 * Personal API tokens, keyed by the hash of their secret for authentication.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/**
 * Inserts the token unless its owner already holds `maxUsable` usable tokens
 * (not revoked, not yet expired at `createdAt`) in the organization, in which
 * case nothing is written and `null` comes back. The count and the insert
 * share one transaction so concurrent requests cannot both squeeze under it.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  maxUsable: number,
): Promise<ApiToken | null> {
  return getDb().transaction(
    (tx) => {
      const used = tx
        .select({ value: count() })
        .from(apiTokens)
        .where(
          and(
            orgPredicate(apiTokens.orgId, token.orgId),
            eq(apiTokens.userId, token.userId),
            isNull(apiTokens.revokedAt),
            gt(apiTokens.expiresAt, token.createdAt),
          ),
        )
        .get();

      if ((used?.value ?? 0) >= maxUsable) return null;

      const row = tx
        .insert(apiTokens)
        .values({
          id: newId(),
          orgId: token.orgId,
          userId: token.userId,
          name: token.name,
          scope: token.scope,
          prefix: token.prefix,
          tokenHash: token.tokenHash,
          expiresAt: token.expiresAt,
          lastUsedAt: null,
          revokedAt: null,
          createdAt: token.createdAt,
          updatedAt: token.createdAt,
        })
        .returning()
        .get();

      return toApiToken(row);
    },
    { behavior: "immediate" },
  );
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Authentication runs before any `Actor` exists, so like the invitation lookup
 * this read is not scoped by `orgId` — the hash is the credential and carries
 * the tenant with it.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Every token `userId` holds in `orgId`, revoked and expired included, newest
 * first. `rowid` breaks ties between tokens minted in the same millisecond.
 */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), sql`rowid desc`)
    .all();

  return rows.map(toApiToken);
}

/**
 * Revokes one token. Resolves `null` when the token was already revoked (or
 * does not exist), so a repeat revocation never moves `revokedAt`.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes every not-yet-revoked token `userId` holds in `orgId`. */
export async function revokeApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

/** Stamps a successful authentication; a revoked token is left untouched. */
export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .run();
}

