export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  maxUsable: number,
): Promise<ApiToken | null> {
  return getDb().transaction(
    (tx) => {
      const used = tx
        .select({ value: count() })
        .from(apiTokens)
        .where(
          and(
            orgPredicate(apiTokens.orgId, token.orgId),
            eq(apiTokens.userId, token.userId),
            isNull(apiTokens.revokedAt),
            gt(apiTokens.expiresAt, token.createdAt),
