    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (apiToken === null) {
    throw new Error(
      `A member may hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens per organization; revoke one first`,
    );
  }

  await emit("api_token.created", {
    orgId: apiToken.orgId,
    actorId: actor.userId,
    occurredAt: apiToken.createdAt,
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/**
 * One user's tokens in the organization, revoked and expired included, newest
 * first. Anyone may list their own; listing someone else's is an admin task.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, userId));
  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

/**
 * Revokes a token. Revoking one that is already revoked is a no-op that
 * returns it unchanged and publishes nothing.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, existing.userId));

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );

  // Lost a race with another revocation: that one already published the fact.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await publishRevoked(revoked, actor.userId);
  return revoked;
}

/**
 * Resolves a presented secret to the `Actor` it acts as, or `null` when the
 * token is unknown, revoked or expired, its organization is gone, or its owner
 * is no longer an active member. A `read` token always acts as a viewer; a
 * `write` token takes the owner's role as it stands right now.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) {
    return null;
  }

  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null || apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(apiToken.orgId, apiToken.id, now);

  return {
    userId: member.userId,
    orgId: member.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * A removed member's tokens stop working the moment they leave: every token
 * they hold in that organization that is not already revoked is revoked, and
 * each revocation is attributed to whoever removed them.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revoked = await apiTokenRepo.revokeApiTokensForUser(
      payload.orgId,
      payload.userId,
      toIsoTimestamp(new Date()),
    );

    for (const apiToken of revoked) {
      await publishRevoked(apiToken, payload.actorId);
    }
  });
}

async function publishRevoked(
  apiToken: ApiToken,
  actorId: UserId | null,
): Promise<void> {
  await emit("api_token.revoked", {
    ...envelope(apiToken.orgId, actorId),
    occurredAt: apiToken.revokedAt ?? toIsoTimestamp(new Date()),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });
}

