    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2030-01-01T00:00:00.000Z");
    vi.setSystemTime(start);
    const t = await createTenant("t3");
    const { token, apiToken } = await svc.createApiToken(t.actors.member, input(t.org.id, { scope: "write", expiresInDays: 1 }));
    const r = await svc.createApiToken(t.actors.member, input(t.org.id, { scope: "read", expiresInDays: 2 }));
    expect(await svc.authenticateApiToken("tfk_nope")).toBeNull();
    const a = await svc.authenticateApiToken(token);
    expect(a).toEqual({ userId: t.userIds.member, orgId: t.org.id, role: "member" });
