    const mine2 = await svc.createApiToken(t.actors.member, input(t.org.id, { scope: "write" }));
    await expect(svc.listApiTokens(t.actors.viewer, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await svc.listApiTokens(t.actors.admin, t.org.id, t.userIds.member)).toHaveLength(2);
    await expect(svc.listApiTokens(t.actors.admin, t2.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(svc.revokeApiToken(t.actors.viewer, t.org.id, mine.apiToken.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(svc.revokeApiToken(t.actors.admin, t.org.id, "01HZZZZZZZZZZZZZZZZZZZZZZZ")).rejects.toBeInstanceOf(NotFoundError);
    const rv = await svc.revokeApiToken(t.actors.admin, t.org.id, mine.apiToken.id);
    expect(rv.revokedAt).not.toBeNull();
    const rv2 = await svc.revokeApiToken(t.actors.member, t.org.id, mine.apiToken.id);
    expect(rv2).toEqual(rv);
    expect(await svc.authenticateApiToken(mine.token)).toBeNull();
    // other org token for same user? member user only in t; make owner token in t2 (owner of t4b is different user)
    const ownerOther = await svc.createApiToken(t2.actors.member, input(t2.org.id));
    const m = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: m!.id });
    const after = await svc.listApiTokens(t.actors.admin, t.org.id, t.userIds.member);
    expect(after.find((x) => x.id === mine.apiToken.id)?.revokedAt).toBe(rv.revokedAt);
    expect(after.find((x) => x.id === mine2.apiToken.id)?.revokedAt).not.toBeNull();
    expect(await svc.authenticateApiToken(mine2.token)).toBeNull();
    expect(await svc.authenticateApiToken(ownerOther.token)).not.toBeNull();
    const revokedRows = (await activityRepo.listActivity(activityFilterSchema.parse({ orgId: t.org.id, action: ["api_token.revoked"] }))).items;
    expect(revokedRows).toHaveLength(2);
    expect(revokedRows.every((r) => r.actorId === t.userIds.admin && r.subjectKind === "api_token")).toBe(true);
    // deleted org
    await orgRepo.archiveOrg(t2.org.id);
    expect(await svc.authenticateApiToken(ownerOther.token)).toBeNull();
  });
});
